arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at `/tmp/sv-47322b998e5d4c41bf7069361e810913/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

This is a two-project setup:
- **ShipmentTracker** (server project): `/tmp/sv-47322b998e5d4c41bf7069361e810913/ShipmentTracker/ShipmentTracker/`
- **ShipmentTracker.Client** (WebAssembly client): `/tmp/sv-47322b998e5d4c41bf7069361e810913/ShipmentTracker/ShipmentTracker.Client/`

## Architecture Rules (Auto mode)
- All interactive components MUST go in the `.Client` project under `Pages/`
- Components cannot access DbContext or server-only services directly
- Data access pattern: Define interface in `.Client` → implement with HttpClient in `.Client` → implement with direct DB access in server → register both in respective Program.cs → expose server data via minimal API endpoints
- Both Program.cs files must register matching services
- Don't add `@rendermode` to pages — global interactivity is already configured

## Requirements
1. **Dispatchers** view a list of shipments with status and destination
2. **Customers** check their shipment status and estimated delivery
3. **Every page has interactive controls**
4. **Individual accounts authentication** (already scaffolded)

## Tasks

### 1. Create the Shipment data model

In the server project `Data/` folder, create `Shipment.cs`:

```csharp
namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}
```

### 2. Create shared DTOs in the Client project

Create `ShipmentTracker.Client/Models/ShipmentDto.cs`:

```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
}

public class CreateShipmentDto
{
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string? CustomerEmail { get; set; }
    public string? Notes { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
}

public class UpdateShipmentStatusDto
{
    public string Status { get; set; } = string.Empty;
    public string? Notes { get; set; }
}

public class TrackingResultDto
{
    public bool Found { get; set; }
    public ShipmentDto? Shipment { get; set; }
    public string? ErrorMessage { get; set; }
}
```

### 3. Create the service interface in the Client project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:

```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentAsync(int id);
    Task<TrackingResultDto> TrackShipmentAsync(string trackingNumber);
    Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto);
    Task<ShipmentDto?> UpdateStatusAsync(int id, UpdateShipmentStatusDto dto);
    Task<bool> DeleteShipmentAsync(int id);
}
```

### 4. Create the Client-side HttpClient implementation

Create `ShipmentTracker.Client/Services/ShipmentServiceClient.cs`:

```csharp
namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        return await _http.GetFromJsonAsync<ShipmentDto>($"api/shipments/{id}");
    }

    public async Task<TrackingResultDto> TrackShipmentAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadFromJsonAsync<TrackingResultDto>() ?? new TrackingResultDto { Found = false, ErrorMessage = "Unexpected error." };
        }
        return new TrackingResultDto { Found = false, ErrorMessage = "Shipment not found." };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", dto);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }

    public async Task<ShipmentDto?> UpdateStatusAsync(int id, UpdateShipmentStatusDto dto)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", dto);
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<ShipmentDto>();
        return null;
    }

    public async Task<bool> DeleteShipmentAsync(int id)
    {
        var response = await _http.DeleteAsync($"api/shipments/{id}");
        return response.IsSuccessStatusCode;
    }
}
```

### 5. Create the Server-side direct implementation

Create `ShipmentTracker/Services/ShipmentServiceServer.cs`:

```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServiceServer : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServiceServer(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var s = await _db.Shipments.FindAsync(id);
        return s is null ? null : ToDto(s);
    }

    public async Task<TrackingResultDto> TrackShipmentAsync(string trackingNumber)
    {
        var s = await _db.Shipments.FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
        if (s is null)
            return new TrackingResultDto { Found = false, ErrorMessage = "No shipment found with that tracking number." };
        return new TrackingResultDto { Found = true, Shipment = ToDto(s) };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = ShipmentStatus.Pending,
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            CustomerEmail = dto.CustomerEmail,
            Notes = dto.Notes
        };
        _db.Shipments.Add(shipment);
        await _db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task<ShipmentDto?> UpdateStatusAsync(int id, UpdateShipmentStatusDto dto)
    {
        var s = await _db.Shipments.FindAsync(id);
        if (s is null) return null;
        if (Enum.TryParse<ShipmentStatus>(dto.Status, true, out var status))
            s.Status = status;
        if (dto.Notes is not null)
            s.Notes = dto.Notes;
        await _db.SaveChangesAsync();
        return ToDto(s);
    }

    public async Task<bool> DeleteShipmentAsync(int id)
    {
        var s = await _db.Shipments.FindAsync(id);
        if (s is null) return false;
        _db.Shipments.Remove(s);
        await _db.SaveChangesAsync();
        return true;
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";
    }
}
```

### 6. Add DbSet to ApplicationDbContext

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
public DbSet<Shipment> Shipments => Set<Shipment>();
```
Read the existing file first and add it properly.

### 7. Create minimal API endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:

```csharp
namespace ShipmentTracker.Endpoints;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("{id:int}", async (int id, IShipmentService service) =>
        {
            var dto = await service.GetShipmentAsync(id);
            return dto is null ? Results.NotFound() : Results.Ok(dto);
        });

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
            Results.Ok(await service.TrackShipmentAsync(trackingNumber)))
            .AllowAnonymous();

        group.MapPost("", async (CreateShipmentDto dto, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/{created.Id}", created);
        });

        group.MapPut("{id:int}/status", async (int id, UpdateShipmentStatusDto dto, IShipmentService service) =>
        {
            var updated = await service.UpdateStatusAsync(id, dto);
            return updated is null ? Results.NotFound() : Results.Ok(updated);
        });

        group.MapDelete("{id:int}", async (int id, IShipmentService service) =>
        {
            var deleted = await service.DeleteShipmentAsync(id);
            return deleted ? Results.NoContent() : Results.NotFound();
        });
    }
}
```

