### 7. Create minimal API endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:

```csharp
namespace ShipmentTracker.Endpoints;

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("{id:int}", async (int id, IShipmentService service) =>
        {
            var dto = await service.GetShipmentAsync(id);
            return dto is null ? Results.NotFound() : Results.Ok(dto);
        });

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
            Results.Ok(await service.TrackShipmentAsync(trackingNumber)))
            .AllowAnonymous();

        group.MapPost("", async (CreateShipmentDto dto, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/{created.Id}", created);
        });

        group.MapPut("{id:int}/status", async (int id, UpdateShipmentStatusDto dto, IShipmentService service) =>
        {
            var updated = await service.UpdateStatusAsync(id, dto);
            return updated is null ? Results.NotFound() : Results.Ok(updated);
        });

        group.MapDelete("{id:int}", async (int id, IShipmentService service) =>
        {
            var deleted = await service.DeleteShipmentAsync(id);
            return deleted ? Results.NoContent() : Results.NotFound();
        });
    }
}
```

