@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchTrackingNumber = string.Empty;
    private TrackingResultDto? result;
    private bool isLoading;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchTrackingNumber = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(searchTrackingNumber)) return;
        isLoading = true;
        result = null;
        try
        {
            result = await ShipmentService.TrackShipmentAsync(searchTrackingNumber.Trim());
        }
        catch
        {
            result = new TrackingResultDto { Found = false, ErrorMessage = "An error occurred while tracking. Please try again." };
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "InTransit" or "OutForDelivery" => "bg-primary",
        "PickedUp" => "bg-info text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}
```

