```csharp
namespace ShipmentTracker.Services;

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

public class ShipmentServiceServer : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServiceServer(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        var s = await _db.Shipments.FindAsync(id);
        return s is null ? null : ToDto(s);
    }

    public async Task<TrackingResultDto> TrackShipmentAsync(string trackingNumber)
    {
        var s = await _db.Shipments.FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
        if (s is null)
            return new TrackingResultDto { Found = false, ErrorMessage = "No shipment found with that tracking number." };
        return new TrackingResultDto { Found = true, Shipment = ToDto(s) };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = ShipmentStatus.Pending,
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            CustomerEmail = dto.CustomerEmail,
            Notes = dto.Notes
        };
        _db.Shipments.Add(shipment);
        await _db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task<ShipmentDto?> UpdateStatusAsync(int id, UpdateShipmentStatusDto dto)
    {
        var s = await _db.Shipments.FindAsync(id);
        if (s is null) return null;
        if (Enum.TryParse<ShipmentStatus>(dto.Status, true, out var status))
            s.Status = status;
        if (dto.Notes is not null)
            s.Notes = dto.Notes;
        await _db.SaveChangesAsync();
        return ToDto(s);
    }

    public async Task<bool> DeleteShipmentAsync(int id)
    {
        var s = await _db.Shipments.FindAsync(id);
        if (s is null) return false;
        _db.Shipments.Remove(s);
        await _db.SaveChangesAsync();
        return true;
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString("N")[..8].ToUpperInvariant()}";
    }
}
