namespace ShipmentTracker.Client.Services;

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

public class ShipmentServiceClient : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentServiceClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentAsync(int id)
    {
        return await _http.GetFromJsonAsync<ShipmentDto>($"api/shipments/{id}");
    }

    public async Task<TrackingResultDto> TrackShipmentAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadFromJsonAsync<TrackingResultDto>() ?? new TrackingResultDto { Found = false, ErrorMessage = "Unexpected error." };
        }
        return new TrackingResultDto { Found = false, ErrorMessage = "Shipment not found." };
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentDto dto)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", dto);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }

    public async Task<ShipmentDto?> UpdateStatusAsync(int id, UpdateShipmentStatusDto dto)
    {
        var response = await _http.PutAsJsonAsync($"api/shipments/{id}/status", dto);
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<ShipmentDto>();
        return null;
    }

    public async Task<bool> DeleteShipmentAsync(int id)
    {
        var response = await _http.DeleteAsync($"api/shipments/{id}");
        return response.IsSuccessStatusCode;
    }
}
