@page "/track"
@page "/track/{TrackingNumber}"
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mt-3">
    <div class="col-md-8">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260710-A1B2C3D4)"
                   @bind="searchTrackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (result is not null)
{
    <div class="mt-4">
        @if (result.Found && result.Shipment is not null)
        {
            var s = result.Shipment;
            <div class="card">
                <div class="card-header">
                    <strong>@s.TrackingNumber</strong>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6">
                            <dl>
                                <dt>Status</dt>
                                <dd><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></dd>
                                <dt>Origin</dt>
                                <dd>@s.Origin</dd>
                                <dt>Destination</dt>
                                <dd>@s.Destination</dd>
                            </dl>
                        </div>
                        <div class="col-md-6">
                            <dl>
                                <dt>Shipped On</dt>
                                <dd>@s.CreatedAt.ToString("MMMM dd, yyyy")</dd>
                                <dt>Estimated Delivery</dt>
                                <dd>
                                    @if (s.EstimatedDelivery.HasValue)
                                    {
                                        @s.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")
                                    }
                                    else
                                    {
                                        <span class="text-muted">Not yet available</span>
                                    }
                                </dd>
                            </dl>
                        </div>
                    </div>
                    @if (!string.IsNullOrWhiteSpace(s.Notes))
                    {
                        <div class="mt-2">
                            <strong>Notes:</strong> @s.Notes
                        </div>
                    }
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning">
                @(result.ErrorMessage ?? "Shipment not found.")
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchTrackingNumber = string.Empty;
    private TrackingResultDto? result;
    private bool isLoading;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchTrackingNumber = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
