@code {
    private List<ShipmentDto>? shipments;
    private bool isLoading = true;
    private bool isSaving;
    private string filterText = string.Empty;
    private string sortColumn = "CreatedAt";
    private bool sortAscending;

    private bool showCreateForm;
    private CreateShipmentDto newShipment = new();
    private ShipmentDto? editingShipment;
    private UpdateShipmentStatusDto statusUpdate = new();
    private ShipmentDto? deletingShipment;

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];
            var filtered = string.IsNullOrWhiteSpace(filterText)
                ? shipments
                : shipments.Where(s => s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                    || s.Origin.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                    || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase));

            return sortColumn switch
            {
                "TrackingNumber" => sortAscending ? filtered.OrderBy(s => s.TrackingNumber) : filtered.OrderByDescending(s => s.TrackingNumber),
                "Origin" => sortAscending ? filtered.OrderBy(s => s.Origin) : filtered.OrderByDescending(s => s.Origin),
                "Destination" => sortAscending ? filtered.OrderBy(s => s.Destination) : filtered.OrderByDescending(s => s.Destination),
                "Status" => sortAscending ? filtered.OrderBy(s => s.Status) : filtered.OrderByDescending(s => s.Status),
                "EstimatedDelivery" => sortAscending ? filtered.OrderBy(s => s.EstimatedDelivery) : filtered.OrderByDescending(s => s.EstimatedDelivery),
                _ => filtered
            };
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            shipments = [];
        }
        finally
        {
            isLoading = false;
        }
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column) =>
        sortColumn != column ? "" : sortAscending ? "▲" : "▼";

    private void ShowCreateForm()
    {
        newShipment = new CreateShipmentDto();
        showCreateForm = true;
    }

    private void ShowStatusEditor(ShipmentDto shipment)
    {
        editingShipment = shipment;
        statusUpdate = new UpdateShipmentStatusDto { Status = shipment.Status };
    }

    private void ConfirmDelete(ShipmentDto shipment)
    {
        deletingShipment = shipment;
    }

    private void CloseModals()
    {
        showCreateForm = false;
        editingShipment = null;
        deletingShipment = null;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination)) return;
        isSaving = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            CloseModals();
            await LoadShipments();
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task UpdateStatus()
    {
        if (editingShipment is null) return;
        isSaving = true;
        try
        {
            await ShipmentService.UpdateStatusAsync(editingShipment.Id, statusUpdate);
            CloseModals();
            await LoadShipments();
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task DeleteShipment()
    {
        if (deletingShipment is null) return;
        isSaving = true;
        try
        {
            await ShipmentService.DeleteShipmentAsync(deletingShipment.Id);
            CloseModals();
            await LoadShipments();
        }
        finally
        {
            isSaving = false;
        }
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "InTransit" or "OutForDelivery" => "bg-primary",
        "PickedUp" => "bg-info text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

